           using var activity =  StartCallActivity("SetBusinessAccountGiftSettingsAsync", typeof(SetBusinessAccountGiftSettings).FullName ?? "SetBusinessAccountGiftSettingsAsync");

           try
           {
             return client.SetBusinessAccountGiftSettingsAsync(businessConnectionId, settings);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
